document.Document:
class Document(BaseModel):
    """A complete reMarkable document with metadata, content info, and pages.

    This is the top-level container that combines all the separate files
    on the device filesystem into a single coherent object. It unifies:

    - {UUID}.metadata -- display name, folder, sync state (DocumentMetadata)
    - {UUID}.content  -- page list, file type, tool settings (ContentInfo)
    - {UUID}/*.rm     -- per-page stroke data (list of Page)
    - {UUID}.pagedata -- per-page template names (list of str)

    Use this model to represent a fully loaded document for rendering,
    export, or analysis.
    """

    uuid: UUID = Field(
        description="Unique identifier for the document. All associated files on "
        "disk use this UUID as their filename stem.",
    )
    metadata: DocumentMetadata = Field(
        description="Parsed .metadata file: display name, folder hierarchy, sync state.",
    )
    content: ContentInfo = Field(
        description="Parsed .content file: page structure, file type, layout settings.",
    )
    pages: list[Page] = Field(
        default_factory=list,
        description="Loaded page data with layers and strokes. May be empty if "
        "only metadata was loaded without parsing .rm files.",
    )
    templates: list[str] = Field(
        default_factory=list,
        description="Per-page template names from the .pagedata file. "
        "One entry per page, in page order.",
    )

    @computed_field  # type: ignore[prop-decorator]
    @property
    def name(self) -> str:
        """The user-visible document name from metadata."""
        return self.metadata.visible_name

    @computed_field  # type: ignore[prop-decorator]
    @property
    def is_notebook(self) -> bool:
        """Whether this document is a native notebook (created on device)."""
        return self.content.file_type == FileType.NOTEBOOK

    @computed_field  # type: ignore[prop-decorator]
    @property
    def is_pdf(self) -> bool:
        """Whether this document is an uploaded/annotated PDF."""
        return self.content.file_type == FileType.PDF

    @computed_field  # type: ignore[prop-decorator]
    @property
    def is_epub(self) -> bool:
        """Whether this document is an uploaded/annotated EPUB."""
        return self.content.file_type == FileType.EPUB

    @computed_field  # type: ignore[prop-decorator]
    @property
    def is_folder(self) -> bool:
        """Whether this entry is a folder (collection), not a document."""
        return self.metadata.doc_type == DocumentType.COLLECTION

    @computed_field  # type: ignore[prop-decorator]
    @property
    def is_trashed(self) -> bool:
        """Whether this document is in the trash (by parent or deleted flag)."""
        return self.metadata.parent == "trash" or self.metadata.deleted

    def base_path(self, xochitl_dir: Path) -> Path:
        """Base path for all this document's files within the xochitl directory.

        Args:
            xochitl_dir: Path to the xochitl directory on the device.

        Returns:
            Path like ``/home/root/.local/share/remarkable/xochitl/{uuid}``.
        """
        return xochitl_dir / str(self.uuid)

page.Layer:
class Layer(BaseModel):
    """A single drawing layer within a page.

    Layers contain strokes (pen drawings) and optionally text blocks.
    They can be shown/hidden and named in the UI. The reMarkable supports
    multiple layers per page, allowing users to organize content
    (e.g. sketch on one layer, annotations on another).

    Layers are rendered bottom-to-top in list order.
    """

    name: str = Field(
        default="",
        description="Optional layer name shown in the reMarkable UI layer panel.",
    )
    visible: bool = Field(
        default=True,
        description="Whether the layer is visible. Hidden layers are skipped during rendering.",
    )
    strokes: list[Stroke] = Field(
        default_factory=list,
        description="Ordered list of strokes (pen drawings) in this layer. "
        "Strokes are rendered in list order (earlier strokes appear behind later ones).",
    )
    text_blocks: list[TextBlock] = Field(
        default_factory=list,
        description="Typed text blocks in this layer. Text is rendered on top of strokes.",
    )

    @computed_field  # type: ignore[prop-decorator]
    @property
    def is_empty(self) -> bool:
        """Whether the layer has no content (no strokes and no text blocks)."""
        return not self.strokes and not self.text_blocks

    @computed_field  # type: ignore[prop-decorator]
    @property
    def bounding_box(self) -> tuple[float, float, float, float]:
        """Return (x_min, y_min, x_max, y_max) bounding box of all strokes.

        Returns (0, 0, 0, 0) if the layer has no strokes.
        Text blocks are not included in the bounding box calculation.
        """
        if not self.strokes:
            return (0.0, 0.0, 0.0, 0.0)
        boxes = [s.bounding_box for s in self.strokes]
        return (
            min(b[0] for b in boxes),
            min(b[1] for b in boxes),
            max(b[2] for b in boxes),
            max(b[3] for b in boxes),
        )

page.Page:
class Page(BaseModel):
    """A single page in a notebook or annotated document.

    Each page is stored as a separate .rm file on the device filesystem
    at ``{document_uuid}/{page_uuid}.rm``. Pages are identified by UUID
    and referenced from the document's .content JSON file.

    A page contains one or more layers and an optional template reference
    that defines the background pattern (lines, grid, dots, etc.).
    """

    uuid: UUID = Field(
        description="Unique identifier for this page. Used as the filename stem "
        "for the .rm file, metadata JSON, and thumbnail JPEG.",
    )
    layers: list[Layer] = Field(
        default_factory=list,
        description="Ordered list of drawing layers. Rendered bottom-to-top.",
    )
    template_name: str = Field(
        default="",
        description="Name of the background template (e.g. 'Blank', 'Lined', 'Grid_small'). "
        "Empty string means no template / blank background.",
    )

    @computed_field  # type: ignore[prop-decorator]
    @property
    def rm_filename(self) -> str:
        """The .rm filename for this page, e.g. '{uuid}.rm'."""
        return f"{self.uuid}.rm"

    @computed_field  # type: ignore[prop-decorator]
    @property
    def metadata_filename(self) -> str:
        """The per-page metadata JSON filename, e.g. '{uuid}-metadata.json'."""
        return f"{self.uuid}-metadata.json"

    @computed_field  # type: ignore[prop-decorator]
    @property
    def thumbnail_filename(self) -> str:
        """The thumbnail JPEG filename, e.g. '{uuid}.jpg'."""
        return f"{self.uuid}.jpg"

    @computed_field  # type: ignore[prop-decorator]
    @property
    def all_strokes(self) -> list[Stroke]:
        """All strokes across all visible layers, in render order."""
        return [s for layer in self.layers if layer.visible for s in layer.strokes]

    def rm_path(self, document_uuid: UUID) -> Path:
        """Full relative path to the .rm file within the xochitl directory.

        Args:
            document_uuid: The parent document's UUID.

        Returns:
            Path like ``{document_uuid}/{page_uuid}.rm``.
        """
        return Path(str(document_uuid)) / self.rm_filename

screen.ScreenSpec:
class ScreenSpec(BaseModel):
    """Physical screen specification for a reMarkable device.

    Defines the pixel dimensions and DPI of a device's e-ink display.
    All coordinates in .rm files are in screen units (pixels), so this
    specification is needed to convert to physical units for export to
    PDF, SVG, or PNG at correct scale.

    The reMarkable 2 and Paper Pro have slightly different screen sizes
    and DPIs, which affects page layout when rendering.
    """

    model_config = ConfigDict(frozen=True)

    width: int = Field(
        description="Screen width in pixels (portrait orientation). "
        "1404 for rM1/rM2, 1620 for Paper Pro.",
    )
    height: int = Field(
        description="Screen height in pixels (portrait orientation). "
        "1872 for rM1/rM2, 2160 for Paper Pro.",
    )
    dpi: int = Field(
        description="Display dots per inch. 226 for rM1/rM2, 229 for Paper Pro. "
        "Used to convert between screen units and physical measurements.",
    )
    name: str = Field(
        description="Human-readable device name, e.g. 'reMarkable 2' or 'Paper Pro'.",
    )

    @computed_field  # type: ignore[prop-decorator]
    @property
    def points_per_pixel(self) -> float:
        """Convert screen units to PDF points (1/72 inch).

        This ratio is used when rendering .rm content into PDF pages
        to ensure strokes appear at the correct physical size.
        """
        return 72.0 / self.dpi

    @computed_field  # type: ignore[prop-decorator]
    @property
    def page_width_pt(self) -> float:
        """Page width in PDF points (1/72 inch)."""
        return self.width * self.points_per_pixel

    @computed_field  # type: ignore[prop-decorator]
    @property
    def page_height_pt(self) -> float:
        """Page height in PDF points (1/72 inch)."""
        return self.height * self.points_per_pixel

    @computed_field  # type: ignore[prop-decorator]
    @property
    def page_width_inches(self) -> float:
        """Page width in inches."""
        return self.width / self.dpi

    @computed_field  # type: ignore[prop-decorator]
    @property
    def page_height_inches(self) -> float:
        """Page height in inches."""
        return self.height / self.dpi

stroke.Stroke:
class Stroke(BaseModel):
    """A single stroke (line) drawn by the stylus.

    Corresponds to a SceneLineItemBlock in the v6 .rm format. A stroke
    captures everything needed to replay one continuous pen-down to pen-up
    movement: the tool used, its color, the thickness scale from the UI
    slider, and the ordered sequence of sampled points.

    Strokes are the fundamental drawing primitive in the reMarkable system.
    All handwritten content is composed of strokes organized into layers.
    """

    pen_type: PenType = Field(
        description="The pen tool used for this stroke. Determines rendering "
        "behavior (line width formula, opacity, sensitivity to pressure/tilt/speed).",
    )
    color: PenColor = Field(
        description="The color index for this stroke. On monochrome devices "
        "(rM1/rM2) only BLACK, GRAY, WHITE are available. Paper Pro adds colors.",
    )
    thickness_scale: float = Field(
        description="Raw thickness scale from the UI thickness slider. This value "
        "is transformed by pen-specific formulas into the actual rendered width.",
    )
    points: list[Point] = Field(
        default_factory=list,
        description="Ordered sequence of stylus sample points from pen-down to "
        "pen-up. Empty strokes are valid (e.g. single-tap dots).",
    )
    starting_length: float = Field(
        default=0.0,
        description="Cumulative length offset for multi-segment rendering. "
        "Used when a stroke is split across multiple rendering passes.",
    )

    @computed_field  # type: ignore[prop-decorator]
    @property
    def is_eraser(self) -> bool:
        """Whether this stroke is an eraser (point or area)."""
        return PenType.is_eraser(self.pen_type)

    @computed_field  # type: ignore[prop-decorator]
    @property
    def is_highlighter(self) -> bool:
        """Whether this stroke is a highlighter variant."""
        return PenType.is_highlighter(self.pen_type)

    @computed_field  # type: ignore[prop-decorator]
    @property
    def bounding_box(self) -> tuple[float, float, float, float]:
        """Return (x_min, y_min, x_max, y_max) bounding box of all points.

        Returns (0, 0, 0, 0) for strokes with no points.
        """
        if not self.points:
            return (0.0, 0.0, 0.0, 0.0)
        xs = [p.x for p in self.points]
        ys = [p.y for p in self.points]
        return (min(xs), min(ys), max(xs), max(ys))
